@dataclass(frozen=True)
class RateSegment(CanonicalMixin):
    """One window of a stream's piecewise rate schedule. A segment reserves `allocation` tokens for the half-open window `[start_time, end_time)` and accrues them pro rata over `basis_seconds`: ```text floor(allocation * elapsed_within_window / basis_seconds) ``` `basis_seconds` is normally the window's own length, which makes the term exact (no rounding at all) whenever `allocation` is a whole multiple of it — the shape every renegotiated segment has, because it is priced as `amount_per_second * window_length`. It is the *original* stream duration for the first segment of a renegotiated stream, whose `allocation` is the deposit the schedule started from: keeping that pair untouched is what makes an accepted change unable to re-price the past. Because each window is a sub-interval of the stream, the elapsed part of it is never longer than `basis_seconds`, which is the condition [`validate_capacity`] needs to guarantee the product cannot overflow."""
    start_time: int
    end_time: int
    allocation: int
    basis_seconds: int

    @classmethod
    def from_scval(cls, value: ScVal, context: str = 'RateSegment') -> RateSegment:
        fields = _struct_fields(value, context)
        start_time = _decode_u64(_field(fields, 'start_time', 'RateSegment.start_time'), 'RateSegment.start_time')
        end_time = _decode_u64(_field(fields, 'end_time', 'RateSegment.end_time'), 'RateSegment.end_time')
        allocation = _decode_i128(_field(fields, 'allocation', 'RateSegment.allocation'), 'RateSegment.allocation')
        basis_seconds = _decode_u64(_field(fields, 'basis_seconds', 'RateSegment.basis_seconds'), 'RateSegment.basis_seconds')
        return cls(start_time, end_time, allocation, basis_seconds)

def _encode_RateSegment(value: RateSegment, context: str) -> ScVal:
    entries = []
    entries.append((ScVal('symbol', 'start_time'), _encode_u64(value.start_time, 'RateSegment.start_time')))
    entries.append((ScVal('symbol', 'end_time'), _encode_u64(value.end_time, 'RateSegment.end_time')))
    entries.append((ScVal('symbol', 'allocation'), _encode_i128(value.allocation, 'RateSegment.allocation')))
    entries.append((ScVal('symbol', 'basis_seconds'), _encode_u64(value.basis_seconds, 'RateSegment.basis_seconds')))
    return ScVal('map', tuple(sorted(entries, key=lambda entry: _scval_sort_key(entry[0]))))

