    name: ClassVar[str] = 'StreamCreated'
    contract_id: str
    topic_fields: ClassVar[tuple[str, ...]] = ('stream_id',)
    data_fields: ClassVar[tuple[str, ...]] = ('sender', 'recipient', 'token', 'deposit', 'start_time', 'end_time', 'cancelable')
    stream_id: int
    sender: str
    recipient: str
    token: str
    deposit: int
    start_time: int
    end_time: int
    cancelable: bool

    @classmethod
    def from_parts(cls, event: ContractEvent, context: str = 'StreamCreated') -> StreamCreated:
        if event.event_type != 1 or event.topics is None or event.data is None:
            raise DecodeError(f'{context}: expected a contract event body')
        topics = event.topics
        if len(topics) != 2:
            raise DecodeError(f'{context}: expected 2 event topics, got {len(topics)}')
        stream_id = _decode_u64(_topic(topics, 1, context), 'StreamCreated.stream_id')
        data = _struct_fields(event.data, 'StreamCreated')
        sender = _decode_address(_field(data, 'sender', context), 'StreamCreated.sender')
        recipient = _decode_address(_field(data, 'recipient', context), 'StreamCreated.recipient')
        token = _decode_address(_field(data, 'token', context), 'StreamCreated.token')
        deposit = _decode_i128(_field(data, 'deposit', context), 'StreamCreated.deposit')
        start_time = _decode_u64(_field(data, 'start_time', context), 'StreamCreated.start_time')
        end_time = _decode_u64(_field(data, 'end_time', context), 'StreamCreated.end_time')
        cancelable = _decode_bool(_field(data, 'cancelable', context), 'StreamCreated.cancelable')
        return cls(contract_id=event.contract_id, stream_id=stream_id, sender=sender, recipient=recipient, token=token, deposit=deposit, start_time=start_time, end_time=end_time, cancelable=cancelable)

